/**
 * Real F1 car telemetry (FastF1 / official timing) resampled to equal-distance.
 * Generated by scripts/fetch-f1-telemetry.py — not a physics guess.
 */
import spaJson from '@/track/data/spa-telemetry.json'
import monzaJson from '@/track/data/monza-telemetry.json'
import texasJson from '@/track/data/texas-telemetry.json'

export type TelemetryTrace = {
  /** km/h */
  speed_kmh: number[]
  /** 0–100 */
  throttle: number[]
  /** 0–100 (often binary from public car data) */
  brake: number[]
  lap_ms: number
  driver: string
  team: string
  distance_m: number
}

export type TrackTelemetry = {
  trackId: string
  source: string
  /** Faster / reference lap */
  a: TelemetryTrace
  /** Comparison lap */
  b: TelemetryTrace
}

const BY_ID: Record<string, TrackTelemetry> = {
  spa: spaJson as TrackTelemetry,
  monza: monzaJson as TrackTelemetry,
  texas: texasJson as TrackTelemetry,
}

export function trackTelemetry(trackId: string): TrackTelemetry | null {
  return BY_ID[trackId] ?? null
}

/** Linear sample of an equal-distance series at lap fraction t ∈ [0, 1]. */
export function sampleTrace(
  series: readonly number[],
  t: number,
): number {
  const n = series.length
  if (n === 0) return 0
  if (n === 1) return series[0]!
  const u = ((t % 1) + 1) % 1
  const f = u * (n - 1)
  const i0 = Math.floor(f)
  const i1 = Math.min(n - 1, i0 + 1)
  const s = f - i0
  return series[i0]! + (series[i1]! - series[i0]!) * s
}
